package com.vandorlabs.vehicle;
import java.util.*;import net.minecraft.util.math.*;import net.minecraft.world.WorldServer;
/** Bounded read-only diagnostics for the retained released-section regression. */
public final class VehicleArmSplitGeometryChecks {
 private static final class Shape{final EntityGroundVehicle craft;final VehicleStructure.Cell cell;final AxisAlignedBB world;Shape(EntityGroundVehicle c,VehicleStructure.Cell cell,AxisAlignedBB b){craft=c;this.cell=cell;world=b;}}
 private static List<Shape> shapes(EntityGroundVehicle c){List<Shape> out=new ArrayList<>();for(VehicleStructure.Cell cell:c.structure.cells){List<AxisAlignedBB> local=new ArrayList<>();cell.state.addCollisionBoxToList(c.view,cell.pos,c.structure.bounds.grow(16),local,null,false);for(AxisAlignedBB b:local){double minX=Double.POSITIVE_INFINITY,minY=minX,minZ=minX,maxX=Double.NEGATIVE_INFINITY,maxY=maxX,maxZ=maxX;for(int k=0;k<8;k++){Vec3d v=c.toWorld(new Vec3d((k&1)==0?b.minX:b.maxX,(k&2)==0?b.minY:b.maxY,(k&4)==0?b.minZ:b.maxZ),cell.pos);minX=Math.min(minX,v.x);minY=Math.min(minY,v.y);minZ=Math.min(minZ,v.z);maxX=Math.max(maxX,v.x);maxY=Math.max(maxY,v.y);maxZ=Math.max(maxZ,v.z);}out.add(new Shape(c,cell,new AxisAlignedBB(minX,minY,minZ,maxX,maxY,maxZ)));}}return out;}
 public static void run(EntityGroundVehicle retained){if(!(retained.world instanceof WorldServer)||!((WorldServer)retained.world).getMinecraftServer().isCallingFromMinecraftThread()||System.getProperty("vandorlabs.reprolab")==null)throw new IllegalStateException("Owning-thread diagnostic only");List<EntityGroundVehicle> owners=new ArrayList<>();for(net.minecraft.entity.Entity entity:new ArrayList<>(retained.world.loadedEntityList))if(entity instanceof EntityGroundVehicle&&!entity.isDead&&entity.getDistanceSq(retained)<900&&((EntityGroundVehicle)entity).structure!=null)owners.add((EntityGroundVehicle)entity);int count=0,printed=0;for(EntityGroundVehicle c:owners){System.out.println("[vandorlabs][reprolab] orphan-geometry owner="+c.getUniqueID()+" origin="+c.posX+","+c.posY+","+c.posZ+" yaw="+c.rotationYaw+" bounds="+c.structure.bounds+" active="+c.articulation.active());for(VehicleArmCouplers.Head head:VehicleArmCouplers.observe(c).heads){Vec3d at=c.toWorld(new Vec3d(head.x,head.y,head.z),head.carrier);System.out.println("[vandorlabs][reprolab] orphan-geometry head="+head.address+" worldPivot="+at+" requested="+head.requested+" locked="+head.locked);}}
 for(int i=0;i<owners.size();i++)for(int j=i+1;j<owners.size();j++)for(Shape a:shapes(owners.get(i)))for(Shape b:shapes(owners.get(j))){double x=Math.min(a.world.maxX,b.world.maxX)-Math.max(a.world.minX,b.world.minX),y=Math.min(a.world.maxY,b.world.maxY)-Math.max(a.world.minY,b.world.minY),z=Math.min(a.world.maxZ,b.world.maxZ)-Math.max(a.world.minZ,b.world.minZ);if(x<=1e-6||y<=1e-6||z<=1e-6)continue;count++;if(printed++<16)System.out.println("[vandorlabs][reprolab] orphan-overlap a="+a.craft.getUniqueID()+"/"+a.cell.pos+"/"+a.cell.state+" "+a.world+" b="+b.craft.getUniqueID()+"/"+b.cell.pos+"/"+b.cell.state+" "+b.world+" positiveOverlap="+x+","+y+","+z);}
 System.out.println("[vandorlabs][reprolab] orphan-geometry crossOwnerPositiveAabbPairs="+count+" (all-axis aligned saved outputs use exact emitted boxes)");}
private VehicleArmSplitGeometryChecks(){}
}
